mkdir -p /tmp/probe && cd /tmp/probe && cat > p.mjs <<'EOF'
import { execFileSync } from 'node:child_process';
const EXE='/workspace/dataset/test19_executable';
// slot: 'a' basic, 'd' extra+tables, 'e' codehilite+fenced, 'f' toc, '5' all+xhtml
const MK={a:'MKAA',b:'MKBB',c:'MKCC',d:'MKDD',e:'MKEE',f:'MKFF'};
export function run(args){
  const a=[];for(const k of ['a','b','c','d','e','f']) a.push('--'+k, args[k]);
  try{ return execFileSync(EXE,a,{encoding:'utf8'});}catch(e){ return 'ERR:'+e.status+'\n'+(e.stdout||'')+(e.stderr||''); }
}
export function phase(slot, s){
  const args={...MK}; args[slot==='5'?'a':slot]=s;
  const out=run(args);
  const lines=out.split('\n');
  // find phase boundaries: phase1_a,1_b,1_c,2_d,2_e,2_f,3,4,5
  // markers produce exactly '<p>MKXX</p>'
  const idx=(m)=>lines.indexOf('<p>'+m+'</p>');
  if(slot==='5'){
    // last phase: find start = after phase4 (article close)
    let i=lines.length-1; while(i>=0 && lines[i].trim()==='') i--;
    // find line ending with </article>
    let j=i; while(j>=0 && !lines[j].includes('</article>')) j--;
    return lines.slice(j+1,i+1).join('\n');
  }
  const order=['a','b','c','d','e','f'];
  const pos=order.indexOf(slot);
  // start: 0 if a, else after previous marker lines
  let start=0;
  for(let k=0;k<pos;k++) start=lines.indexOf('<p>'+MK[order[k]]+'</p>',start)+1;
  let end=start;
  if(pos<5){ for(let k=pos+1;k<6;k++){} end=lines.indexOf('<p>'+MK[order[pos+1]]+'</p>',start); }
  else { // f: next is phase3 which starts with '<h1>Combined Document</h1>'
    end=lines.indexOf('<h1>Combined Document</h1>',start);
  }
  return lines.slice(start,end).join('\n');
}
if(process.argv[2]){ console.log(JSON.stringify(phase(process.argv[2], process.argv[3]))); }
