mkdir -p /tmp/probe /tmp/specs && cd /tmp/probe && cat > p.mjs <<'PEOF'
import { execFileSync } from 'node:child_process';
export const EXE = '/workspace/dataset/test19_executable';
export const MK = { a:'MKAA', b:'MKBB', c:'MKCC', d:'MKDD', e:'MKEE', f:'MKFF' };
const ORDER = ['a','b','c','d','e','f'];

/** Run the executable with an explicit {a,b,c,d,e,f} map. Returns full stdout. */
export function run(args) {
  const argv = [];
  for (const k of ORDER) argv.push('--' + k, args[k] === undefined ? MK[k] : args[k]);
  try { return execFileSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 }); }
  catch (e) { return 'ERR(' + e.status + ')\n' + (e.stdout || '') + (e.stderr || ''); }
}

/**
 * Isolate one printed phase.
 *  slot 'a'|'b'|'c'  -> markdown.markdown(text)                       (no extensions)
 *  slot 'd'          -> extensions=['extra','tables']
 *  slot 'e'          -> extensions=['codehilite','fenced_code']
 *  slot 'f'          -> extensions=['toc']
 *  slot '5'          -> phase5: all 5 extensions + output_format='xhtml'
 *                       (text goes in --f so it is the tail of the concatenated doc)
 */
export function phase(slot, s) {
  if (slot === '5') return phase5(s);
  const args = { ...MK }; args[slot] = s;
  const out = run(args);
  const lines = out.split('\n');
  const pos = ORDER.indexOf(slot);
  let start = 0;
  for (let k = 0; k < pos; k++) start = lines.indexOf('<p>' + MK[ORDER[k]] + '</p>', start) + 1;
  const end = pos < 5 ? lines.indexOf('<p>' + MK[ORDER[pos + 1]] + '</p>', start)
                      : lines.indexOf('<h1>Combined Document</h1>', start);
  return lines.slice(start, end).join('\n');
}

/** phase5 of a document whose last arg is `s`; returns only the tail after the 5 marker paragraphs. */
export function phase5(s) {
  const args = { ...MK }; args.f = s;
  const out = run(args);
  const lines = out.split('\n');
  let i = lines.length - 1;
  while (i >= 0 && lines[i] === '') i--;            // strip trailing blank from print()
  let j = i; while (j >= 0 && !lines[j].includes('</article>')) j--;   // end of phase4
  const tail = lines.slice(j + 1, i + 1);
  const k = tail.lastIndexOf('<p>' + MK.e + '</p>');
  return tail.slice(k + 1).join('\n');
}

/** Full raw output for the 6 given args (no isolation). */
export function full(a, b, c, d, e, f) { return run({ a, b, c, d, e, f }); }

if (process.argv[2]) console.log(JSON.stringify(phase(process.argv[2], process.argv[3])));
