import { phase } from './p.mjs';
for (const [slot, s] of JSON.parse(process.argv[2])) {
  console.log('### slot=' + slot + ' IN=' + JSON.stringify(s));
  console.log('OUT=' + JSON.stringify(phase(slot, s)));
}
