/**
 * Low-level character utilities.
 *
 * The whole library is written without regular expressions: every pattern the
 * original Python implementation expresses as a regex is re-expressed here as a
 * hand written character scan built on these predicates.
 */

export const STX = '';
export const ETX = '';

/** Placeholder wrapped around stashed raw HTML blocks. */
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';
export const HTML_PLACEHOLDER_SUFFIX = ETX;
/** Placeholder wrapped around a processed inline chunk. */
export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const INLINE_PLACEHOLDER_SUFFIX = ETX;
/** Stand-in for a literal ampersand that must survive entity mangling. */
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;

export function htmlPlaceholder(i) {
  return HTML_PLACEHOLDER_PREFIX + i + HTML_PLACEHOLDER_SUFFIX;
}
export function inlinePlaceholder(i) {
  return INLINE_PLACEHOLDER_PREFIX + i + INLINE_PLACEHOLDER_SUFFIX;
}

/** Characters markdown lets you escape with a backslash. */
export const ESCAPED_CHARS = '\\`*_{}[]()>#+-.!';

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}
export function isHexDigit(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}
export function isOctDigit(ch) {
  return ch >= '0' && ch <= '7';
}
export function isBinDigit(ch) {
  return ch === '0' || ch === '1';
}
export function isAsciiLower(ch) {
  return ch >= 'a' && ch <= 'z';
}
export function isAsciiUpper(ch) {
  return ch >= 'A' && ch <= 'Z';
}
export function isAsciiAlpha(ch) {
  return isAsciiLower(ch) || isAsciiUpper(ch);
}
export function isAsciiAlnum(ch) {
  return isAsciiAlpha(ch) || isDigit(ch);
}
/** ASCII `\w`: letters, digits and underscore. */
export function isWordChar(ch) {
  return isAsciiAlnum(ch) || ch === '_';
}

/**
 * Unicode-aware `\w`, matching Python's `re` module on `str` input: letters,
 * decimal digits, marks, connector punctuation and a few compatibility cases.
 */
export function isUnicodeWordChar(ch) {
  if (ch === undefined || ch === '') return false;
  if (isWordChar(ch)) return true;
  const code = ch.codePointAt(0);
  if (code < 128) return false;
  return UNICODE_WORD_CACHE.has(ch) ? UNICODE_WORD_CACHE.get(ch) : computeUnicodeWord(ch);
}
const UNICODE_WORD_CACHE = new Map();
function computeUnicodeWord(ch) {
  // A character counts as a word character when its uppercase or lowercase form
  // differs (letters) or when it is a decimal digit in some script, which we
  // approximate by checking `Number` conversion of the single character.
  let result = false;
  const lower = ch.toLowerCase();
  const upper = ch.toUpperCase();
  if (lower !== upper) result = true;
  else if (!isSeparator(ch) && !isAsciiPunct(ch)) {
    // Ideographs, kana, and other caseless letters land here. Control and
    // punctuation characters are excluded by the checks below.
    const code = ch.codePointAt(0);
    result = !isUnicodePunctOrSymbol(code) && code > 0xa0;
  }
  UNICODE_WORD_CACHE.set(ch, result);
  return result;
}
function isUnicodePunctOrSymbol(code) {
  // General punctuation, CJK punctuation, fullwidth forms punctuation blocks.
  if (code >= 0x2000 && code <= 0x206f) return true;
  if (code >= 0x2190 && code <= 0x2bff) return true;
  if (code >= 0x3000 && code <= 0x303f) return true;
  if (code >= 0xfe30 && code <= 0xfe4f) return true;
  if (code >= 0xff01 && code <= 0xff0f) return true;
  if (code >= 0xff1a && code <= 0xff20) return true;
  if (code >= 0xff3b && code <= 0xff40) return true;
  if (code >= 0xff5b && code <= 0xff65) return true;
  if (code >= 0x1f000 && code <= 0x1ffff) return true;
  if (code >= 0x2600 && code <= 0x27bf) return true;
  return false;
}

/** Python's `str.isspace()` for a single character. */
export function isSpace(ch) {
  if (ch === undefined || ch === '') return false;
  if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f') return true;
  const code = ch.codePointAt(0);
  if (code < 128) return code === 0x1c || code === 0x1d || code === 0x1e || code === 0x1f;
  return (
    code === 0x85 || code === 0xa0 || code === 0x1680 ||
    (code >= 0x2000 && code <= 0x200a) ||
    code === 0x2028 || code === 0x2029 || code === 0x202f ||
    code === 0x205f || code === 0x3000
  );
}
/** Horizontal whitespace only: what markdown treats as intra-line padding. */
export function isBlank(ch) {
  return ch === ' ' || ch === '\t';
}
export function isSeparator(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\v' || ch === '\f';
}
export function isAsciiPunct(ch) {
  return '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~'.indexOf(ch) !== -1;
}

/** True when every character of `s` is whitespace (empty string counts). */
export function isAllSpace(s) {
  for (let i = 0; i < s.length; i++) if (!isSpace(s[i])) return false;
  return true;
}
/** Python's `str.strip()` semantics. */
export function pyStrip(s) {
  let a = 0;
  let b = s.length;
  while (a < b && isSpace(s[a])) a++;
  while (b > a && isSpace(s[b - 1])) b--;
  return s.slice(a, b);
}
export function pyLStrip(s) {
  let a = 0;
  while (a < s.length && isSpace(s[a])) a++;
  return s.slice(a);
}
export function pyRStrip(s) {
  let b = s.length;
  while (b > 0 && isSpace(s[b - 1])) b--;
  return s.slice(0, b);
}
/** Strip only the characters present in `chars` (Python's `strip(chars)`). */
export function stripChars(s, chars) {
  let a = 0;
  let b = s.length;
  while (a < b && chars.indexOf(s[a]) !== -1) a++;
  while (b > a && chars.indexOf(s[b - 1]) !== -1) b--;
  return s.slice(a, b);
}
export function rstripChars(s, chars) {
  let b = s.length;
  while (b > 0 && chars.indexOf(s[b - 1]) !== -1) b--;
  return s.slice(0, b);
}
export function lstripChars(s, chars) {
  let a = 0;
  while (a < s.length && chars.indexOf(s[a]) !== -1) a++;
  return s.slice(a);
}

/** Number of leading space characters. */
export function leadingSpaces(line) {
  let n = 0;
  while (n < line.length && line[n] === ' ') n++;
  return n;
}

/** Repeat-free `startsWith` for a set of prefixes. */
export function startsWithAny(s, prefixes, from = 0) {
  for (const p of prefixes) if (s.startsWith(p, from)) return p;
  return null;
}

/** Split a string on a single character without regular expressions. */
export function splitChar(s, ch) {
  const out = [];
  let start = 0;
  for (;;) {
    const i = s.indexOf(ch, start);
    if (i === -1) { out.push(s.slice(start)); return out; }
    out.push(s.slice(start, i));
    start = i + ch.length;
  }
}

/** Replace every occurrence of `find` with `repl` (plain string search). */
export function replaceAll(s, find, repl) {
  if (find === '') return s;
  let out = '';
  let start = 0;
  for (;;) {
    const i = s.indexOf(find, start);
    if (i === -1) return out + s.slice(start);
    out += s.slice(start, i) + repl;
    start = i + find.length;
  }
}

/** Python's `str.expandtabs(tabsize)`. */
export function expandTabs(s, tabsize = 4) {
  let out = '';
  let col = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '\t') {
      if (tabsize > 0) {
        const width = tabsize - (col % tabsize);
        out += ' '.repeat(width);
        col += width;
      }
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      col = 0;
    } else {
      out += ch;
      col++;
    }
  }
  return out;
}

/** True when the string contains only the given character, at least `min` times. */
export function isRunOf(s, ch, min = 1) {
  if (s.length < min) return false;
  for (let i = 0; i < s.length; i++) if (s[i] !== ch) return false;
  return true;
}

/** Case-insensitive comparison restricted to ASCII, like Python's `str.lower()` on tags. */
export function asciiLower(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    out += isAsciiUpper(ch) ? String.fromCharCode(ch.charCodeAt(0) + 32) : ch;
  }
  return out;
}

