/**
 * A minimal element tree, mirroring the subset of Python's `xml.etree`
 * behaviour that the markdown pipeline depends on: ordered attributes,
 * `text`/`tail` slots, and document-order iteration.
 */

export class Element {
  constructor(tag, attrib) {
    this.tag = tag;
    /** Insertion-ordered attribute map. */
    this.attrib = new Map();
    if (attrib) for (const k of Object.keys(attrib)) this.attrib.set(k, attrib[k]);
    this.text = null;
    this.tail = null;
    this.children = [];
  }

  get(name, fallback = null) {
    return this.attrib.has(name) ? this.attrib.get(name) : fallback;
  }
  set(name, value) {
    this.attrib.set(name, value);
  }
  has(name) {
    return this.attrib.has(name);
  }
  delete(name) {
    this.attrib.delete(name);
  }
  keys() {
    return [...this.attrib.keys()];
  }
  items() {
    return [...this.attrib.entries()];
  }

  append(child) {
    this.children.push(child);
    return child;
  }
  insert(index, child) {
    this.children.splice(index, 0, child);
    return child;
  }
  remove(child) {
    const i = this.children.indexOf(child);
    if (i !== -1) this.children.splice(i, 1);
  }
  extend(children) {
    for (const c of children) this.children.push(c);
  }
  clear() {
    this.attrib.clear();
    this.children.length = 0;
    this.text = null;
    this.tail = null;
  }
  index(child) {
    return this.children.indexOf(child);
  }
  get length() {
    return this.children.length;
  }
  at(i) {
    return this.children[i];
  }

  /** Depth-first document-order iteration, optionally filtered by tag. */
  *iter(tag = null) {
    if (tag === null || this.tag === tag) yield this;
    for (const c of this.children) yield* c.iter(tag);
  }
  /** Direct children matching `tag`. */
  findall(tag) {
    return this.children.filter((c) => c.tag === tag);
  }
  find(tag) {
    for (const c of this.children) if (c.tag === tag) return c;
    return null;
  }
  /** Map of child -> parent for the whole subtree. */
  parentMap() {
    const map = new Map();
    const walk = (el) => {
      for (const c of el.children) {
        map.set(c, el);
        walk(c);
      }
    };
    walk(this);
    return map;
  }
}

export function SubElement(parent, tag, attrib) {
  return parent.append(new Element(tag, attrib));
}

/**
 * Marker wrapper: text that must not be touched by inline processing.
 * Python-Markdown uses a `str` subclass; we use a boxed value plus a set so
 * identity survives assignment to `text`/`tail` slots.
 */
const ATOMIC = new Set();
export function atomicString(s) {
  // Strings are primitives in JS, so remember the exact value in a registry and
  // let `isAtomic` answer by lookup. False positives are harmless because an
  // identical string produced elsewhere would be treated as literal text too.
  ATOMIC.add(s);
  return s;
}
export function isAtomic(s) {
  return typeof s === 'string' && ATOMIC.has(s);
}
export function clearAtomic() {
  ATOMIC.clear();
}

