/**
 * HTML / XHTML serialization of the element tree, reproducing the exact
 * escaping and attribute-ordering rules of the reference implementation:
 * attributes are emitted in sorted order, and `&` is only escaped when it does
 * not already introduce a character reference.
 */

import { isAsciiAlnum, isDigit, isHexDigit } from './util.mjs';

/** Elements serialized without a closing tag. */
export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

/** Tags whose text content is emitted verbatim. */
const RAW_TEXT_TAGS = new Set(['script', 'style']);

/** Pseudo tags used for comments and processing instructions. */
export const COMMENT = '#comment';
export const PI = '#pi';

/**
 * True when the `&` at `i` starts a character reference (`&#123;`, `&#xAF;`
 * or `&name;`), which must then be left untouched.
 */
function startsEntity(text, i) {
  let j = i + 1;
  if (j < text.length && text[j] === '#') {
    j++;
    if (j < text.length && (text[j] === 'x' || text[j] === 'X')) {
      j++;
      const start = j;
      while (j < text.length && isHexDigit(text[j])) j++;
      return j > start && text[j] === ';';
    }
    const start = j;
    while (j < text.length && isDigit(text[j])) j++;
    return j > start && text[j] === ';';
  }
  const start = j;
  while (j < text.length && isAsciiAlnum(text[j])) j++;
  return j > start && text[j] === ';';
}

function escapeAmp(text) {
  if (text.indexOf('&') === -1) return text;
  let out = '';
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '&' && !startsEntity(text, i)) out += '&amp;';
    else out += text[i];
  }
  return out;
}

/** Escaping applied to character data (element text and tails). */
export function escapeCdata(text) {
  let out = escapeAmp(text);
  if (out.indexOf('<') !== -1) out = out.split('<').join('&lt;');
  if (out.indexOf('>') !== -1) out = out.split('>').join('&gt;');
  return out;
}

/** Escaping applied to attribute values. */
export function escapeAttrib(text) {
  let out = escapeAmp(String(text));
  if (out.indexOf('<') !== -1) out = out.split('<').join('&lt;');
  if (out.indexOf('>') !== -1) out = out.split('>').join('&gt;');
  if (out.indexOf('"') !== -1) out = out.split('"').join('&quot;');
  if (out.indexOf('\n') !== -1) out = out.split('\n').join('&#10;');
  return out;
}

function serializeInto(parts, elem, format) {
  const tag = elem.tag;
  if (tag === COMMENT) {
    parts.push('<!--' + (elem.text || '') + '-->');
  } else if (tag === PI) {
    parts.push('<?' + (elem.text || '') + '?>');
  } else if (tag === null) {
    if (elem.text) parts.push(escapeCdata(elem.text));
    for (const child of elem.children) serializeInto(parts, child, format);
  } else {
    parts.push('<' + tag);
    const items = [...elem.attrib.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
    for (const [k, v] of items) {
      if (v === null || v === undefined) {
        // Boolean attribute: XHTML requires a value, HTML allows the bare name.
        if (format === 'xhtml') parts.push(' ' + k + '="' + escapeAttrib(k) + '"');
        else parts.push(' ' + k);
      } else {
        parts.push(' ' + k + '="' + escapeAttrib(v) + '"');
      }
    }
    const lower = tag.toLowerCase();
    if (format === 'xhtml' && HTML_EMPTY.has(lower)) {
      parts.push(' />');
    } else {
      parts.push('>');
      if (elem.text) parts.push(RAW_TEXT_TAGS.has(lower) ? elem.text : escapeCdata(elem.text));
      for (const child of elem.children) serializeInto(parts, child, format);
      if (!HTML_EMPTY.has(lower)) parts.push('</' + tag + '>');
    }
  }
  if (elem.tail) parts.push(escapeCdata(elem.tail));
}

/** Serialize `elem` using `format` (`'xhtml'` or `'html'`). */
export function serialize(elem, format = 'xhtml') {
  const parts = [];
  serializeInto(parts, elem, format);
  return parts.join('');
}

