/**
 * Priority registry: an ordered collection of named processors, iterated from
 * highest to lowest priority. Mirrors the extension-facing registry API of the
 * reference implementation so extensions can insert themselves at a precise
 * point in the pipeline.
 */

export class Registry {
  constructor() {
    this._entries = []; // {name, priority, item}
    this._sorted = null;
  }

  register(item, name, priority) {
    this.deregister(name, false);
    this._entries.push({ name, priority, item });
    this._sorted = null;
    return this;
  }

  deregister(name, strict = true) {
    const i = this._entries.findIndex((e) => e.name === name);
    if (i === -1) {
      if (strict) throw new Error('No item named "' + name + '" exists.');
      return this;
    }
    this._entries.splice(i, 1);
    this._sorted = null;
    return this;
  }

  has(name) {
    return this._entries.some((e) => e.name === name);
  }

  get(name) {
    const e = this._entries.find((x) => x.name === name);
    if (!e) throw new Error('No item named "' + name + '" exists.');
    return e.item;
  }

  /** Items ordered by descending priority; ties keep registration order. */
  items() {
    if (this._sorted === null) {
      const indexed = this._entries.map((e, i) => ({ e, i }));
      indexed.sort((x, y) => (y.e.priority - x.e.priority) || (x.i - y.i));
      this._sorted = indexed.map((x) => x.e.item);
    }
    return this._sorted;
  }

  [Symbol.iterator]() {
    return this.items()[Symbol.iterator]();
  }

  get length() {
    return this._entries.length;
  }
}

