/**
 * Raw-HTML stash.
 *
 * Raw HTML found in the source is pulled out of the document before block
 * parsing and replaced by an opaque placeholder, then re-inserted verbatim by
 * the raw-html postprocessor. Keeping the HTML out of the tree is what lets
 * already-rendered HTML survive a second trip through the parser unchanged --
 * which is exactly what the phase 3 and phase 4 stages of the pipeline do.
 */

import { htmlPlaceholder } from './util.mjs';

export class HtmlStash {
  constructor() {
    this.rawHtmlBlocks = [];
    this.tagCounter = 0;
    this.tagData = [];
  }

  /** Stash `html` and return the placeholder that stands in for it. */
  store(html) {
    const placeholder = this.getPlaceholder(this.rawHtmlBlocks.length);
    this.rawHtmlBlocks.push(html);
    return placeholder;
  }

  reset() {
    this.rawHtmlBlocks = [];
    this.tagCounter = 0;
    this.tagData = [];
  }

  getPlaceholder(key) {
    return htmlPlaceholder(key);
  }
}

