/**
 * HTML tokenizer + raw-block extractor.
 *
 * A port of the tolerant HTML tokenizer the reference implementation relies on,
 * driving the extractor that pulls raw HTML out of the document and replaces it
 * with stash placeholders. Written as an explicit character scanner: no regular
 * expressions are used anywhere.
 */

import { isAsciiAlpha, isAsciiAlnum, isSpace, pyStrip, asciiLower } from './util.mjs';

/** Elements whose content is CDATA, i.e. not parsed as markup. */
const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

/** Characters that terminate a tag name. */
function isTagNameEnd(ch) {
  return ch === undefined || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' ||
    ch === ' ' || ch === '/' || ch === '>' || ch === '\0';
}

/** `\s` as understood by the tokenizer's patterns. */
function isWs(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v';
}

/** Scan `(?:\s|/(?!>))*` starting at `i`. */
function skipWsOrSlash(s, i) {
  for (;;) {
    const ch = s[i];
    if (ch === undefined) return i;
    if (isWs(ch)) { i++; continue; }
    if (ch === '/' && s[i + 1] !== '>') { i++; continue; }
    return i;
  }
}

/** Scan `[\s/]*`. */
function skipWsSlashAny(s, i) {
  while (i < s.length && (isWs(s[i]) || s[i] === '/')) i++;
  return i;
}

/** Scan `[a-zA-Z][^\t\n\r\f />\0]*` -- a tag name. Returns end index or -1. */
function scanTagName(s, i) {
  if (!isAsciiAlpha(s[i])) return -1;
  i++;
  while (i < s.length && !isTagNameEnd(s[i])) i++;
  return i;
}

/**
 * Scan one attribute: `((?<=['"\s/])[^\s/>][^\s/=>]*)(\s*=+\s*(VALUE))?(?:\s|/(?!>))*`.
 * Returns the end index, or -1 when no attribute starts here.
 */
function scanAttribute(s, i, prevChar) {
  if (!(prevChar === "'" || prevChar === '"' || prevChar === '/' || isWs(prevChar))) return -1;
  const ch = s[i];
  if (ch === undefined || isWs(ch) || ch === '/' || ch === '>') return -1;
  let j = i + 1;
  while (j < s.length) {
    const c = s[j];
    if (isWs(c) || c === '/' || c === '=' || c === '>') break;
    j++;
  }
  // Optional value: `\s*=+\s*` then a quoted or bare value.
  let k = j;
  while (k < s.length && isWs(s[k])) k++;
  if (s[k] === '=') {
    while (s[k] === '=') k++;
    while (k < s.length && isWs(s[k])) k++;
    const q = s[k];
    if (q === "'" || q === '"') {
      const close = s.indexOf(q, k + 1);
      if (close === -1) return -1; // unterminated quoted value: no match
      k = close + 1;
    } else {
      while (k < s.length && !isWs(s[k]) && s[k] !== '>') k++;
    }
    // `(?:\s*,)*`
    for (;;) {
      let m = k;
      while (m < s.length && isWs(s[m])) m++;
      if (s[m] === ',') { k = m + 1; continue; }
      break;
    }
    j = k;
  }
  return skipWsOrSlash(s, j);
}

/**
 * Scan `locatestarttagend_tolerant` starting at a `<`. Returns the end index of
 * the match (exclusive), which sits just before `>` or `/>` for a well formed tag.
 */
function locateStartTagEnd(s, i) {
  let j = scanTagName(s, i + 1);
  if (j === -1) return -1;
  // `(?:[\s/]* (?:attr)* )?` then `\s*`
  const afterName = j;
  let k = skipWsSlashAny(s, j);
  let last = k;
  for (;;) {
    const prev = k > 0 ? s[k - 1] : '';
    const e = scanAttribute(s, k, prev);
    if (e === -1 || e === k) break;
    k = e;
    last = k;
  }
  if (last === skipWsSlashAny(s, afterName) && last !== afterName) {
    // Only whitespace/slashes consumed and no attribute matched: the greedy
    // `[\s/]*` still applies, so keep it.
    k = last;
  }
  while (k < s.length && isWs(s[k])) k++;
  return k;
}

/** Find the first `-->`-style comment close (`--\s*>`) at or after `i`. */
function findCommentClose(s, i) {
  for (let p = s.indexOf('--', i); p !== -1; p = s.indexOf('--', p + 1)) {
    let q = p + 2;
    while (q < s.length && isSpace(s[q])) q++;
    if (s[q] === '>') return { start: p, end: q + 1 };
  }
  return null;
}

/** Scan an SGML name (`[a-zA-Z][-_.a-zA-Z0-9]*`) for marked sections. */
function scanName(s, i) {
  if (!isAsciiAlpha(s[i])) return null;
  let j = i + 1;
  while (j < s.length && (isAsciiAlnum(s[j]) || s[j] === '-' || s[j] === '_' || s[j] === '.')) j++;
  return { name: asciiLower(s.slice(i, j)), end: j };
}

/** True when `s` from `i` matches `^[ ]*\n`. */
function blankLineAt(s, i) {
  let j = i;
  while (j < s.length && s[j] === ' ') j++;
  return s[j] === '\n';
}

/**
 * Tokenizer + extractor. Feeds the whole document at once (the pipeline never
 * streams), then `close()` flushes anything left over.
 */
export class HTMLExtractor {
  constructor(md) {
    this.md = md;
    this.rawdata = '';
    this.pos = 0;          // absolute index of the token currently handled
    this.cdataElem = null;
    this.emptyTags = new Set(['hr']);
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this._cache = [];
    this.cleandoc = [];
  }

  /* ---------- position helpers ---------- */

  lineStart(pos) {
    const nl = this.rawdata.lastIndexOf('\n', pos - 1);
    return nl === -1 ? 0 : nl + 1;
  }

  atLineStart() {
    const start = this.lineStart(this.pos);
    const offset = this.pos - start;
    if (offset === 0) return true;
    if (offset > 3) return false;
    return pyStrip(this.rawdata.slice(start, this.pos)) === '';
  }

  /* ---------- extractor handlers ---------- */

  isBlockLevel(tag) {
    return this.md.isBlockLevel(tag);
  }

  handleStarttag(tag, startTagText) {
    if (this.emptyTags.has(tag)) {
      this.handleEmptyTag(startTagText, this.isBlockLevel(tag));
      return;
    }
    if (this.isBlockLevel(tag) && (this.intail || (this.atLineStart() && !this.inraw))) {
      this.inraw = true;
      this.cleandoc.push('\n');
    }
    if (this.inraw) {
      this.stack.push(tag);
      this._cache.push(startTagText);
    } else {
      this.cleandoc.push(startTagText);
    }
  }

  handleEndtag(tag, endTagText) {
    if (this.inraw) {
      this._cache.push(endTagText);
      if (this.stack.indexOf(tag) !== -1) {
        while (this.stack.length) if (this.stack.pop() === tag) break;
      }
      if (this.stack.length === 0) {
        if (blankLineAt(this.rawdata, this.pos + endTagText.length)) {
          this._cache.push('\n');
        } else {
          this.intail = true;
        }
        this.inraw = false;
        this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
        this.cleandoc.push('\n\n');
        this._cache = [];
      }
    } else {
      this.cleandoc.push(endTagText);
    }
  }

  handleData(data) {
    if (this.intail && data.indexOf('\n') !== -1) this.intail = false;
    if (this.inraw) this._cache.push(data);
    else this.cleandoc.push(data);
  }

  handleEmptyTag(data, isBlock) {
    if (this.inraw || this.intail) {
      this._cache.push(data);
    } else if (this.atLineStart() && isBlock) {
      let payload = data;
      if (blankLineAt(this.rawdata, this.pos + data.length)) payload += '\n';
      else this.intail = true;
      const item = this.cleandoc.length ? this.cleandoc[this.cleandoc.length - 1] : '';
      if (!item.endsWith('\n\n') && item.endsWith('\n')) this.cleandoc.push('\n');
      this.cleandoc.push(this.md.htmlStash.store(payload));
      this.cleandoc.push('\n\n');
    } else {
      this.cleandoc.push(this.md.htmlStash.store(data));
    }
  }

  handleComment(data) {
    this.handleEmptyTag('<!--' + data + '-->', true);
  }
  handleDecl(data) {
    this.handleEmptyTag('<!' + data + '>', true);
  }
  handlePi(data) {
    this.handleEmptyTag('<?' + data + '>', true);
  }
  unknownDecl(data) {
    const end = data.startsWith('CDATA[') ? ']]>' : ']>';
    this.handleEmptyTag('<![' + data + end, true);
  }

  /* ---------- tokenizer ---------- */

  feed(data) {
    this.rawdata += data;
    this.goahead(false);
  }

  close() {
    this.goahead(true);
    if (this.rawdata.length) {
      this.pos = this.absPos;
      this.handleData(this.rawdata.slice(this.absPos));
      this.absPos = this.rawdata.length;
    }
    if (this._cache.length) {
      this.cleandoc.push(this.md.htmlStash.store(this._cache.join('')));
      this._cache = [];
    }
  }

  /** Index of the next `<` or `&` (or the CDATA end tag while in CDATA mode). */
  nextInteresting(i) {
    const s = this.rawdata;
    if (this.cdataElem) {
      // `</\s*<elem>` case-insensitively.
      for (let p = s.indexOf('</', i); p !== -1; p = s.indexOf('</', p + 1)) {
        let q = p + 2;
        while (q < s.length && isWs(s[q])) q++;
        if (asciiLower(s.slice(q, q + this.cdataElem.length)) === this.cdataElem) return p;
      }
      return -1;
    }
    let best = -1;
    const lt = s.indexOf('<', i);
    const amp = s.indexOf('&', i);
    if (lt === -1) best = amp;
    else if (amp === -1) best = lt;
    else best = Math.min(lt, amp);
    return best;
  }

  goahead(end) {
    const s = this.rawdata;
    let i = this.absPos || 0;
    const n = s.length;
    while (i < n) {
      let j = this.nextInteresting(i);
      if (j === -1) {
        if (this.cdataElem) break;
        j = n;
      }
      if (i < j) {
        this.pos = i;
        this.handleData(s.slice(i, j));
      }
      i = j;
      if (i === n) break;
      let k;
      if (s[i] === '<') {
        this.pos = i;
        if (isAsciiAlpha(s[i + 1])) k = this.parseStarttag(i);
        else if (s.startsWith('</', i)) k = this.parseEndtag(i);
        else if (s.startsWith('<!--', i)) k = this.parseComment(i);
        else if (s.startsWith('<?', i)) k = this.parsePi(i);
        else if (s.startsWith('<!', i)) k = this.parseHtmlDeclaration(i);
        else if (i + 1 < n) { this.handleData('<'); k = i + 1; }
        else { if (!end) break; this.handleData(s.slice(i, n)); k = n; }
        if (k < 0) {
          if (!end) break;
          k = s.indexOf('>', i + 1);
          if (k === -1) {
            k = s.indexOf('<', i + 1);
            if (k === -1) k = i + 1;
          } else {
            k += 1;
          }
          this.pos = i;
          this.handleData(s.slice(i, k));
        }
        i = k;
      } else if (s.startsWith('&#', i)) {
        const m = this.matchCharref(i);
        if (m !== -1) {
          this.pos = i;
          this.handleData(s.slice(i, m));
          i = m;
        } else {
          if (!end) break;
          this.pos = i;
          this.handleData('&#');
          i += 2;
        }
      } else if (s[i] === '&') {
        const m = this.matchEntityref(i);
        if (m !== -1) {
          this.pos = i;
          this.handleData(s.slice(i, m));
          i = m;
        } else {
          this.pos = i;
          this.handleData('&');
          i += 1;
        }
      } else {
        break;
      }
    }
    if (end && i < n && !this.cdataElem) {
      this.pos = i;
      this.handleData(s.slice(i, n));
      i = n;
    }
    this.absPos = i;
    this.rawdata = s;
    if (i >= n) this.rawdataConsumed = true;
  }

  /** `&#(?:[0-9]+|[xX][0-9a-fA-F]+);?` -- returns end index or -1. */
  matchCharref(i) {
    const s = this.rawdata;
    let j = i + 2;
    if (s[j] === 'x' || s[j] === 'X') {
      j++;
      const start = j;
      while (j < s.length && /* hex digit */ ((s[j] >= '0' && s[j] <= '9') || (s[j] >= 'a' && s[j] <= 'f') || (s[j] >= 'A' && s[j] <= 'F'))) j++;
      if (j === start) return -1;
    } else {
      const start = j;
      while (j < s.length && s[j] >= '0' && s[j] <= '9') j++;
      if (j === start) return -1;
    }
    if (s[j] === ';') j++;
    return j;
  }

  /** `&[a-zA-Z][-.a-zA-Z0-9]*;?` -- returns end index or -1. */
  matchEntityref(i) {
    const s = this.rawdata;
    let j = i + 1;
    if (!isAsciiAlpha(s[j])) return -1;
    j++;
    while (j < s.length && (isAsciiAlnum(s[j]) || s[j] === '-' || s[j] === '.')) j++;
    if (s[j] === ';') j++;
    return j;
  }

  checkForWholeStartTag(i) {
    const s = this.rawdata;
    const j = locateStartTagEnd(s, i);
    if (j === -1) return -1;
    const next = s[j] === undefined ? '' : s[j];
    if (next === '>') return j + 1;
    if (next === '/') {
      if (s.startsWith('/>', j)) return j + 2;
      if (s.startsWith('/', j)) return -1;
      return j > i ? j : i + 1;
    }
    if (next === '') return -1;
    if (isAsciiAlpha(next) || next === '=' || next === '/') return -1;
    return j > i ? j : i + 1;
  }

  parseStarttag(i) {
    const s = this.rawdata;
    const endpos = this.checkForWholeStartTag(i);
    if (endpos < 0) return endpos;
    const startTagText = s.slice(i, endpos);
    const nameEnd = scanTagName(s, i + 1);
    const tag = asciiLower(s.slice(i + 1, nameEnd));
    const tail = pyStrip(s.slice(this.startTagAttrEnd(i, endpos), endpos));
    if (tail !== '>' && tail !== '/>') {
      this.pos = i;
      this.handleData(startTagText);
      return endpos;
    }
    this.pos = i;
    if (tail.endsWith('/>')) {
      this.handleEmptyTag(startTagText, this.isBlockLevel(tag));
    } else {
      this.handleStarttag(tag, startTagText);
      if (CDATA_CONTENT_ELEMENTS.has(tag)) this.cdataElem = tag;
    }
    return endpos;
  }

  /**
   * Position where the attribute scan stopped inside a start tag, used to
   * verify the tag really ends with `>` or `/>`.
   */
  startTagAttrEnd(i, endpos) {
    const s = this.rawdata;
    let k = scanTagName(s, i + 1);
    k = skipWsOrSlash(s, k);
    while (k < endpos) {
      const prev = k > 0 ? s[k - 1] : '';
      const e = scanAttribute(s, k, prev);
      if (e === -1 || e === k) break;
      k = e;
    }
    return k;
  }

  parseEndtag(i) {
    const s = this.rawdata;
    let gt = s.indexOf('>', i + 1);
    if (gt === -1) return -1;
    let gtpos = gt + 1;
    // `</\s*([a-zA-Z][-.a-zA-Z0-9:_]*)\s*>`
    let p = i + 2;
    while (p < s.length && isWs(s[p])) p++;
    let q = p;
    if (isAsciiAlpha(s[q])) {
      q++;
      while (q < s.length && (isAsciiAlnum(s[q]) || s[q] === '-' || s[q] === '.' || s[q] === ':' || s[q] === '_')) q++;
    }
    let r = q;
    while (r < s.length && isWs(s[r])) r++;
    const wellFormed = q > p && s[r] === '>';
    if (!wellFormed) {
      if (this.cdataElem !== null) {
        this.pos = i;
        this.handleData(s.slice(i, gtpos));
        return gtpos;
      }
      const nameEnd = scanTagName(s, i + 2);
      if (nameEnd === -1) {
        if (s.startsWith('</>', i)) return i + 3;
        return this.parseBogusComment(i);
      }
      const tagname = asciiLower(s.slice(i + 2, nameEnd));
      const after = skipWsOrSlash(s, nameEnd);
      gtpos = s.indexOf('>', after) + 1;
      this.pos = i;
      this.handleEndtag(tagname, s.slice(i, gtpos));
      return gtpos;
    }
    const elem = asciiLower(s.slice(p, q));
    gtpos = r + 1;
    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.pos = i;
      this.handleData(s.slice(i, gtpos));
      return gtpos;
    }
    this.pos = i;
    this.handleEndtag(elem, this.endtagText(i));
    this.cdataElem = null;
    return gtpos;
  }

  /** The literal source text of the end tag starting at `i`. */
  endtagText(i) {
    const gt = this.rawdata.indexOf('>', i);
    return gt === -1 ? '' : this.rawdata.slice(i, gt + 1);
  }

  parseComment(i) {
    const s = this.rawdata;
    const m = findCommentClose(s, i + 4);
    if (!m) return -1;
    this.pos = i;
    this.handleComment(s.slice(i + 4, m.start));
    return m.end;
  }

  parsePi(i) {
    const s = this.rawdata;
    const gt = s.indexOf('>', i + 2);
    if (gt === -1) return -1;
    this.pos = i;
    this.handlePi(s.slice(i + 2, gt));
    return gt + 1;
  }

  parseHtmlDeclaration(i) {
    const s = this.rawdata;
    if (s.startsWith('<!--', i)) return this.parseComment(i);
    if (s.startsWith('<![', i)) return this.parseMarkedSection(i);
    if (asciiLower(s.slice(i, i + 9)) === '<!doctype') {
      const gt = s.indexOf('>', i + 9);
      if (gt === -1) return -1;
      this.pos = i;
      this.handleDecl(s.slice(i + 2, gt));
      return gt + 1;
    }
    return this.parseBogusComment(i);
  }

  parseBogusComment(i) {
    const s = this.rawdata;
    const pos = s.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.pos = i;
    this.handleComment(s.slice(i + 2, pos));
    return pos + 1;
  }

  parseMarkedSection(i) {
    const s = this.rawdata;
    const nm = scanName(s, i + 3);
    if (!nm) return -1;
    let closeIdx;
    if (['temp', 'cdata', 'ignore', 'include', 'rcdata'].indexOf(nm.name) !== -1) {
      closeIdx = s.indexOf(']]>', i + 3);
      if (closeIdx === -1) return -1;
      this.pos = i;
      this.unknownDecl(s.slice(i + 3, closeIdx));
      return closeIdx + 3;
    }
    if (['if', 'else', 'endif'].indexOf(nm.name) !== -1) {
      closeIdx = s.indexOf(']>', i + 3);
      if (closeIdx === -1) return -1;
      this.pos = i;
      this.unknownDecl(s.slice(i + 3, closeIdx));
      return closeIdx + 2;
    }
    return -1;
  }
}

/** Run the extractor over `source` and return the cleaned document text. */
export function extractHtml(md, source) {
  const parser = new HTMLExtractor(md);
  parser.absPos = 0;
  parser.feed(source);
  parser.close();
  return parser.cleandoc.join('');
}

