/**
 * HTML tokenizer + raw-block extractor.
 *
 * A port of the tolerant HTML tokenizer the reference implementation relies on,
 * driving the extractor that pulls raw HTML out of the document and replaces it
 * with stash placeholders. Written as an explicit character scanner: no regular
 * expressions are used anywhere.
 */

import { isAsciiAlpha, isAsciiAlnum, isSpace, pyStrip, asciiLower } from './util.mjs';

/** Elements whose content is CDATA, i.e. not parsed as markup. */
const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

/** Characters that terminate a tag name. */
function isTagNameEnd(ch) {
  return ch === undefined || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' ||
    ch === ' ' || ch === '/' || ch === '>' || ch === '\0';
}

/** `\s` as understood by the tokenizer's patterns. */
function isWs(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v';
}

/** Scan `(?:\s|/(?!>))*` starting at `i`. */
function skipWsOrSlash(s, i) {
  for (;;) {
    const ch = s[i];
    if (ch === undefined) return i;
    if (isWs(ch)) { i++; continue; }
    if (ch === '/' && s[i + 1] !== '>') { i++; continue; }
    return i;
  }
}

/** Scan `[\s/]*`. */
function skipWsSlashAny(s, i) {
  while (i < s.length && (isWs(s[i]) || s[i] === '/')) i++;
  return i;
}

/** Scan `[a-zA-Z][^\t\n\r\f />\0]*` -- a tag name. Returns end index or -1. */
function scanTagName(s, i) {
  if (!isAsciiAlpha(s[i])) return -1;
  i++;
  while (i < s.length && !isTagNameEnd(s[i])) i++;
  return i;
}

/**
 * Scan one attribute: `((?<=['"\s/])[^\s/>][^\s/=>]*)(\s*=+\s*(VALUE))?(?:\s|/(?!>))*`.
 * Returns the end index, or -1 when no attribute starts here.
 */
function scanAttribute(s, i, prevChar) {
  if (!(prevChar === "'" || prevChar === '"' || prevChar === '/' || isWs(prevChar))) return -1;
  const ch = s[i];
  if (ch === undefined || isWs(ch) || ch === '/' || ch === '>') return -1;
  let j = i + 1;
  while (j < s.length) {
    const c = s[j];
    if (isWs(c) || c === '/' || c === '=' || c === '>') break;
    j++;
  }
  // Optional value: `\s*=+\s*` then a quoted or bare value.
  let k = j;
  while (k < s.length && isWs(s[k])) k++;
  if (s[k] === '=') {
    while (s[k] === '=') k++;
    while (k < s.length && isWs(s[k])) k++;
    const q = s[k];
    if (q === "'" || q === '"') {
      const close = s.indexOf(q, k + 1);
      if (close === -1) return -1; // unterminated quoted value: no match
      k = close + 1;
    } else {
      while (k < s.length && !isWs(s[k]) && s[k] !== '>') k++;
    }
    // `(?:\s*,)*`
    for (;;) {
      let m = k;
      while (m < s.length && isWs(s[m])) m++;
      if (s[m] === ',') { k = m + 1; continue; }
      break;
    }
    j = k;
  }
  return skipWsOrSlash(s, j);
}

/**
 * Scan `locatestarttagend_tolerant` starting at a `<`. Returns the end index of
 * the match (exclusive), which sits just before `>` or `/>` for a well formed tag.
 */
function locateStartTagEnd(s, i) {
  let j = scanTagName(s, i + 1);
  if (j === -1) return -1;
  // `(?:[\s/]* (?:attr)* )?` then `\s*`
  const afterName = j;
  let k = skipWsSlashAny(s, j);
  let last = k;
  for (;;) {
    const prev = k > 0 ? s[k - 1] : '';
    const e = scanAttribute(s, k, prev);
    if (e === -1 || e === k) break;
    k = e;
    last = k;
  }
  if (last === skipWsSlashAny(s, afterName) && last !== afterName) {
    // Only whitespace/slashes consumed and no attribute matched: the greedy
    // `[\s/]*` still applies, so keep it.
    k = last;
  }
  while (k < s.length && isWs(s[k])) k++;
  return k;
}

/** Find the first `-->`-style comment close (`--\s*>`) at or after `i`. */
function findCommentClose(s, i) {
  for (let p = s.indexOf('--', i); p !== -1; p = s.indexOf('--', p + 1)) {
    let q = p + 2;
    while (q < s.length && isSpace(s[q])) q++;
    if (s[q] === '>') return { start: p, end: q + 1 };
  }
  return null;
