        else { if (!end) break; this.handleData(s.slice(i, n)); k = n; }
        if (k < 0) {
          if (!end) break;
          k = s.indexOf('>', i + 1);
          if (k === -1) {
            k = s.indexOf('<', i + 1);
            if (k === -1) k = i + 1;
          } else {
