/** Run the extractor over `source` and return the cleaned document text. */
export function extractHtml(md, source) {
  const parser = new HTMLExtractor(md);
  parser.absPos = 0;
  parser.feed(source);
  parser.close();
  return parser.cleandoc.join('');
}

